import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  // Static HTML/CSS/JS export for Hostinger (no Node.js server). Output: `out/`.
  output: "export",
  turbopack: {
    // Pin the project root: a parent folder contains another package.json/lockfile,
    // which would otherwise be detected as the workspace root.
    root: __dirname,
  },
  // Emit `/en/index.html` and `/ar/index.html` so plain Apache/LiteSpeed hosting
  // resolves every route without rewrite rules.
  trailingSlash: true,
  images: {
    // Responsive variants are pre-generated by `npm run images` and rendered by
    // `components/media/MediaImage.tsx`, so the runtime optimizer is never needed.
    unoptimized: true,
  },
  experimental: {
    // A single bilingual 404 page, since the app has two root layouts.
    globalNotFound: true,
  },
};

export default nextConfig;
